-- Open Process | PostgreSQL
BEGIN;

CREATE TABLE "customers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "seq_2") NOT NULL,
  "email" VARCHAR(200) NOT NULL,
  CONSTRAINT "pk_1" PRIMARY KEY ("id"),
  CONSTRAINT "uq_3" UNIQUE ("email")
);

CREATE TABLE "orders" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "seq_5") NOT NULL,
  "total" DECIMAL(12,2) NOT NULL DEFAULT 0,
  "customers_id" INTEGER,
  CONSTRAINT "pk_4" PRIMARY KEY ("id")
);

CREATE TABLE "order_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "seq_10") NOT NULL,
  "quantity" INTEGER NOT NULL DEFAULT 1,
  "orders_id" INTEGER,
  CONSTRAINT "pk_9" PRIMARY KEY ("id")
);

ALTER TABLE "orders" ADD CONSTRAINT "fk_8" FOREIGN KEY ("customers_id") REFERENCES "customers" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "order_items" ADD CONSTRAINT "fk_13" FOREIGN KEY ("orders_id") REFERENCES "orders" ("id") ON DELETE CASCADE ON UPDATE NO ACTION;

COMMIT;
